def start(self):
    """Start the network: assign host IP addresses.

    Hosts that already carry an address keep it, and the generated addresses
    skip anything already taken, so pinning one host's IP cannot collide with
    an auto-assigned one.
    """
    if not self.built:
        self.build()
    taken = {host.ip for host in self.hosts if host.ip}
    next_index = 0
    for index, host in enumerate(self.hosts):
        if host.ip is None:
            ip = generate_ip(next_index, base=self.ipBaseNum)
            while ip in taken:
                next_index += 1
                ip = generate_ip(next_index, base=self.ipBaseNum)
            host.setIP(ip)
            taken.add(ip)
            next_index += 1
        if self.autoSetMacs and host.mac is None:
            host.setMAC("00:00:00:00:%02x:%02x" %
                        ((index + 1) // 256, (index + 1) % 256))
